insert into public.products (id, slug, category_id, name, brand, model, summary, description, specs, included, quantity, price_24h, price_weekend, unit_label, rental_mode, caution, photos, visible, featured, sort) values ('a5100000-0000-4000-8000-000000000001', 'sono-1600w-elokance', 'sono', 'Sono 1600 W Elokance', 'Elokance', null, 'Deux satellites et un caisson de basses : 1 600 W pour une soirée jusqu''à 100 personnes environ.', 'Un système complet et rapide à installer pour les anniversaires, soirées et réceptions. Il se compose de deux satellites Elokance ELO 10C et d''un caisson de basses amplifié Elokance SUB15A, qui alimente les satellites : il suffit d''y brancher une table de mixage, un téléphone ou un ordinateur pour obtenir un son puissant et équilibré.', '[{"label":"Puissance","value":"800 W RMS (1 600 W crête)"},{"label":"Satellites","value":"2 × Elokance ELO 10C"},{"label":"Caisson de basses","value":"1 × Elokance SUB15A amplifié, 15 pouces"},{"label":"Réponse en fréquence","value":"35 Hz à 19 kHz"},{"label":"Entrées","value":"XLR et jack"}]'::jsonb, '["2 pieds pour les satellites","2 câbles speakON","Câbles d''alimentation"]'::jsonb, 1, 80, 120, 'le système', 'libre', null, '["/photos/sono-1600w-reception.jpg","/photos/elokance-elo10c.jpg","/photos/elokance-sub15a.jpg","/photos/sono-1600w-reception-2.jpg","/photos/sono-1600w-salle-fete.jpg"]'::jsonb, true, true, 1) on conflict (id) do nothing;
insert into public.products (id, slug, category_id, name, brand, model, summary, description, specs, included, quantity, price_24h, price_weekend, unit_label, rental_mode, caution, photos, visible, featured, sort) values ('a5100000-0000-4000-8000-000000000002', 'enceinte-alto-ts410', 'sono', 'Enceinte Alto TS410', 'Alto Professional', 'TS410', 'Enceinte active 10 pouces de 2 000 W crête, avec Bluetooth et mixeur 3 voies intégré.', 'Légère et puissante, la TS410 s''utilise seule pour un discours, en paire pour une fête, ou par quatre avec le caisson TS15S pour un mariage. Son mixeur intégré accepte directement un micro et une source Bluetooth.', '[{"label":"Puissance","value":"1 000 W RMS (2 000 W crête)"},{"label":"Haut-parleurs","value":"Boomer 10 pouces et moteur à compression 1,4 pouce"},{"label":"Pression sonore max.","value":"130 dB"},{"label":"Réponse en fréquence","value":"57 Hz à 20 kHz"},{"label":"Entrées","value":"2 combos XLR/jack et Bluetooth"},{"label":"Poids","value":"11,8 kg"}]'::jsonb, '["Câble d''alimentation"]'::jsonb, 4, 30, 45, 'l''unité', 'libre', null, '["/photos/alto-ts410.jpg"]'::jsonb, true, true, 2) on conflict (id) do nothing;
insert into public.products (id, slug, category_id, name, brand, model, summary, description, specs, included, quantity, price_24h, price_weekend, unit_label, rental_mode, caution, photos, visible, featured, sort) values ('a5100000-0000-4000-8000-000000000003', 'caisson-alto-ts15s', 'sono', 'Caisson de basses Alto TS15S', 'Alto Professional', 'TS15S', 'Caisson actif 15 pouces de 2 500 W crête pour des basses profondes.', 'À associer aux enceintes TS410 pour donner du corps à la musique sur la piste de danse. Il se pose au sol et peut porter une enceinte sur son mât.', '[{"label":"Puissance","value":"2 500 W crête"},{"label":"Haut-parleur","value":"15 pouces"},{"label":"Réponse en fréquence","value":"36 Hz à 140 Hz"},{"label":"Embase de mât","value":"36 mm"},{"label":"Poids","value":"39,6 kg"}]'::jsonb, '["Câble d''alimentation","Câbles XLR de liaison"]'::jsonb, 1, 45, 65, 'l''unité', 'libre', null, '["/photos/alto-ts15s.jpg"]'::jsonb, true, false, 3) on conflict (id) do nothing;
insert into public.products (id, slug, category_id, name, brand, model, summary, description, specs, included, quantity, price_24h, price_weekend, unit_label, rental_mode, caution, photos, visible, featured, sort) values ('a5100000-0000-4000-8000-000000000016', 'enceinte-jbl-partybox-on-the-go', 'sono', 'Enceinte JBL PartyBox On-The-Go', 'JBL', 'PartyBox On-The-Go', 'Enceinte autonome sur batterie, avec jeu de lumières et micro sans fil : la fête partout, même sans prise.', 'Elle se porte à l''épaule et fonctionne sur batterie : idéale pour un apéritif en extérieur, un pique-nique, un karaoké ou une petite fête à la maison. Connectez votre téléphone en Bluetooth : les lumières suivent la musique, et le micro sans fil fourni est prêt pour chanter ou faire un discours.', '[{"label":"Puissance","value":"100 W"},{"label":"Autonomie","value":"Batterie intégrée, jusqu''à 6 h"},{"label":"Connexions","value":"Bluetooth et entrée micro"},{"label":"Lumières","value":"Jeu de lumières synchronisé à la musique"},{"label":"Protection","value":"Résiste aux éclaboussures (IPX4)"},{"label":"Transport","value":"Bandoulière, moins de 8 kg"}]'::jsonb, '["1 micro sans fil","Câble d''alimentation"]'::jsonb, 1, 25, 35, 'l''unité', 'libre', null, '["/photos/jbl-partybox-on-the-go.jpg"]'::jsonb, true, false, 4) on conflict (id) do nothing;
insert into public.products (id, slug, category_id, name, brand, model, summary, description, specs, included, quantity, price_24h, price_weekend, unit_label, rental_mode, caution, photos, visible, featured, sort) values ('a5100000-0000-4000-8000-000000000004', 'table-de-mixage-2-voies', 'sono', 'Table de mixage 2 voies', 'Ibiza Sound', 'MIX500BT', 'Mixeur compact avec Bluetooth, lecteur USB et entrées jack.', 'Pour gérer la musique simplement : branchez votre téléphone en Bluetooth, une clé USB ou une source en jack, puis réglez le volume de chaque voie.', '[{"label":"Voies","value":"2"},{"label":"Sources","value":"Bluetooth, USB et jack"}]'::jsonb, '["Câbles de liaison vers les enceintes"]'::jsonb, 2, 15, 20, 'l''unité', 'libre', null, '["/photos/table-mixage-ibiza-mix500bt.jpg"]'::jsonb, true, false, 5) on conflict (id) do nothing;
insert into public.products (id, slug, category_id, name, brand, model, summary, description, specs, included, quantity, price_24h, price_weekend, unit_label, rental_mode, caution, photos, visible, featured, sort) values ('a5100000-0000-4000-8000-000000000005', 'pioneer-dj-xdj-rr', 'dj', 'Pioneer DJ XDJ-RR', 'Pioneer DJ', 'XDJ-RR', 'Système DJ tout-en-un 2 voies, compatible rekordbox, sans ordinateur.', 'Deux lecteurs et un mixeur dans un seul appareil, avec un grand écran pour parcourir sa musique depuis une clé USB. Location sur demande, pour les DJ expérimentés ou avec notre présence technique sur place.', '[{"label":"Voies","value":"2 lecteurs et mixeur intégrés"},{"label":"Sources","value":"2 ports USB et 1 entrée auxiliaire"},{"label":"Écran","value":"Couleur 7 pouces"},{"label":"Entrée micro","value":"XLR et jack 6,35 mm"},{"label":"Sorties","value":"Master XLR et RCA, 2 sorties casque"},{"label":"Poids","value":"5,2 kg"}]'::jsonb, '["Câble d''alimentation","Câbles XLR vers la sono"]'::jsonb, 1, 90, 140, 'l''unité', 'sur_demande', 1000, '["/photos/pioneer-xdj-rr.jpg"]'::jsonb, true, false, 5) on conflict (id) do nothing;
insert into public.products (id, slug, category_id, name, brand, model, summary, description, specs, included, quantity, price_24h, price_weekend, unit_label, rental_mode, caution, photos, visible, featured, sort) values ('a5100000-0000-4000-8000-000000000006', 'paire-micros-sans-fil-jbl', 'micros', 'Paire de micros sans fil JBL', 'JBL', null, 'Deux micros main sans fil et leur récepteur.', 'Pour les discours, les témoins, le karaoké ou une animation à deux voix. Le récepteur se branche sur la table de mixage ou directement sur une enceinte.', '[{"label":"Micros","value":"2 micros main sans fil"},{"label":"Usage","value":"Discours, karaoké, animation"}]'::jsonb, '["Récepteur","Piles chargées"]'::jsonb, 1, 20, 30, 'la paire', 'libre', null, '["/photos/jbl-micros.jpg"]'::jsonb, true, false, 6) on conflict (id) do nothing;
insert into public.products (id, slug, category_id, name, brand, model, summary, description, specs, included, quantity, price_24h, price_weekend, unit_label, rental_mode, caution, photos, visible, featured, sort) values ('a5100000-0000-4000-8000-000000000007', 'paire-micros-sans-fil', 'micros', 'Paire de micros sans fil', null, null, 'Deux micros main sans fil et leur récepteur.', 'Une deuxième paire pour les événements avec plusieurs intervenants : cérémonies, remises de prix, réunions.', '[{"label":"Micros","value":"2 micros main sans fil"},{"label":"Usage","value":"Discours, cérémonie, animation"}]'::jsonb, '["Récepteur","Piles chargées"]'::jsonb, 1, 20, 30, 'la paire', 'libre', null, '["/photos/micros-sans-fil-ghost.jpg"]'::jsonb, true, false, 7) on conflict (id) do nothing;
insert into public.products (id, slug, category_id, name, brand, model, summary, description, specs, included, quantity, price_24h, price_weekend, unit_label, rental_mode, caution, photos, visible, featured, sort) values ('a5100000-0000-4000-8000-000000000008', 'micro-sans-fil', 'micros', 'Micro sans fil', null, null, 'Un micro main sans fil et son récepteur.', 'La solution simple pour un discours ou un toast, à brancher sur la table de mixage ou sur une enceinte TS410.', '[{"label":"Micro","value":"1 micro main sans fil"},{"label":"Usage","value":"Discours, toast, annonces"}]'::jsonb, '["Récepteur","Piles chargées"]'::jsonb, 1, 12, 18, 'l''unité', 'libre', null, '["/photos/micro-sans-fil.jpg"]'::jsonb, true, false, 8) on conflict (id) do nothing;
insert into public.products (id, slug, category_id, name, brand, model, summary, description, specs, included, quantity, price_24h, price_weekend, unit_label, rental_mode, caution, photos, visible, featured, sort) values ('a5100000-0000-4000-8000-000000000009', 'uplight-led', 'eclairage', 'Uplight LED', null, null, 'Projecteur LED posé au sol pour mettre en couleur les murs, les colonnes et le décor.', 'Placés le long des murs ou au pied des colonnes, les uplights transforment l''ambiance d''une salle de réception. Huit unités suffisent à habiller une salle de mariage.', '[{"label":"Usage","value":"Mise en lumière de murs, colonnes et décor"},{"label":"Disponibles","value":"8 unités"}]'::jsonb, '[]'::jsonb, 8, 7, 10, 'l''unité', 'libre', null, '["/photos/uplight-led.jpg"]'::jsonb, true, true, 9) on conflict (id) do nothing;
insert into public.products (id, slug, category_id, name, brand, model, summary, description, specs, included, quantity, price_24h, price_weekend, unit_label, rental_mode, caution, photos, visible, featured, sort) values ('a5100000-0000-4000-8000-000000000010', 'pied-effets-lyre-laser-strobes', 'eclairage', 'Pied d''effets : lyre, laser et stroboscopes', null, null, 'Un pied complet avec une lyre, un laser et deux stroboscopes pour la piste de danse.', 'Le cœur de l''ambiance dansante : la lyre balaie la salle, le laser trace ses faisceaux et les stroboscopes marquent les temps forts. Livré monté sur son pied, prêt à brancher.', '[{"label":"Composition","value":"1 lyre LED, 1 laser, 2 stroboscopes"},{"label":"Support","value":"Pied avec barre de fixation"}]'::jsonb, '["Rallonge électrique"]'::jsonb, 1, 40, 60, 'le pied complet', 'libre', null, '[]'::jsonb, true, false, 10) on conflict (id) do nothing;
insert into public.products (id, slug, category_id, name, brand, model, summary, description, specs, included, quantity, price_24h, price_weekend, unit_label, rental_mode, caution, photos, visible, featured, sort) values ('a5100000-0000-4000-8000-000000000011', 'pied-4-par-led', 'eclairage', 'Pied de 4 PAR LED', null, null, 'Quatre projecteurs PAR LED sur pied pour colorer la piste ou la scène.', 'Un éclairage coloré et homogène pour la piste de danse, la table des mariés ou une petite scène. Livré monté sur son pied.', '[{"label":"Composition","value":"4 projecteurs PAR LED"},{"label":"Support","value":"Pied avec barre de fixation"}]'::jsonb, '["Rallonge électrique"]'::jsonb, 1, 25, 35, 'le pied complet', 'libre', null, '["/photos/pied-4-par-led.jpg"]'::jsonb, true, false, 11) on conflict (id) do nothing;
insert into public.products (id, slug, category_id, name, brand, model, summary, description, specs, included, quantity, price_24h, price_weekend, unit_label, rental_mode, caution, photos, visible, featured, sort) values ('a5100000-0000-4000-8000-000000000012', 'pied-4-par-led-effets-disco', 'eclairage', 'Pied de 4 PAR LED et 2 effets disco', null, null, 'Quatre PAR LED et deux effets disco sur un même pied.', 'La couleur des PAR LED et le mouvement des effets disco réunis sur un seul pied : idéal pour animer une soirée sans multiplier les installations.', '[{"label":"Composition","value":"4 projecteurs PAR LED et 2 effets disco"},{"label":"Support","value":"Pied avec barre de fixation"}]'::jsonb, '["Rallonge électrique"]'::jsonb, 1, 35, 50, 'le pied complet', 'libre', null, '["/photos/pied-4-par-disco.jpg"]'::jsonb, true, false, 12) on conflict (id) do nothing;
insert into public.products (id, slug, category_id, name, brand, model, summary, description, specs, included, quantity, price_24h, price_weekend, unit_label, rental_mode, caution, photos, visible, featured, sort) values ('a5100000-0000-4000-8000-000000000013', 'machine-a-fumee-500w', 'eclairage', 'Machine à fumée 500 W', null, null, 'Fait ressortir les faisceaux de lumière. Liquide fourni.', 'Quelques secondes de fumée suffisent à révéler les faisceaux de la lyre et du laser. À utiliser seulement si le lieu l''autorise : la fumée peut déclencher certains détecteurs incendie.', '[{"label":"Puissance","value":"500 W"},{"label":"Consommable","value":"Liquide fourni"}]'::jsonb, '["Liquide à fumée","Télécommande"]'::jsonb, 1, 15, 20, 'l''unité', 'libre', null, '["/photos/machine-a-fumee.jpg"]'::jsonb, true, false, 13) on conflict (id) do nothing;
insert into public.products (id, slug, category_id, name, brand, model, summary, description, specs, included, quantity, price_24h, price_weekend, unit_label, rental_mode, caution, photos, visible, featured, sort) values ('a5100000-0000-4000-8000-000000000014', 'pied-enceinte', 'accessoires', 'Pied d''enceinte', null, null, 'Trépied réglable en hauteur, offert avec les enceintes.', 'Placer les enceintes en hauteur améliore nettement la diffusion du son au-dessus du public. Ajoutez autant de pieds que d''enceintes.', '[{"label":"Mât","value":"Standard 35 mm"},{"label":"Hauteur","value":"Réglable"}]'::jsonb, '[]'::jsonb, 4, 0, 0, 'l''unité', 'libre', null, '["/photos/pieds-enceinte.jpg"]'::jsonb, true, false, 14) on conflict (id) do nothing;
